// src/extras/effects/dynamic-sky/wgsl/haze-ps.js
var haze_ps_default2 = (
  /* wgsl */
  `
    #include "dynamicSkyAtmospherePS"

    uniform dynSkyRotation: mat3x3f;    // the rotation of the sky of the scene
    uniform dynSkyHaze: vec4f;          // x: density at the base height, y: one over the height of the haze, z: base height

    // the color of the haze in a world space direction - the sky behind it, without the sun disc,
    // the stars and the moon
    fn dynamicSkyHazeColor(worldDir: vec3f) -> vec3f {

        // to the space of the sky, turned by its rotation and with X flipped. Below the horizon,
        // where the daylight model has no answer, the haze takes the color of the sky just above it
        let turned = worldDir * uniform.dynSkyRotation;
        var dir = vec3f(-turned.x, turned.y, turned.z) / max(length(turned), 1e-6);
        dir.y = max(dir.y, 0.015);

        var ambient: vec3f;
        return dynamicSkyBase(normalize(dir), &ambient);
    }

    // the fraction of a surface hidden by the haze, from its position and the position of the camera
    fn dynamicSkyHazeAmount(cameraPos: vec3f, worldPos: vec3f) -> f32 {
        let b = uniform.dynSkyHaze.y;
        let h0 = cameraPos.y - uniform.dynSkyHaze.z;
        let h1 = worldPos.y - uniform.dynSkyHaze.z;
        let x = b * (h1 - h0);

        // the mean density along the ray, which falls off exponentially with the height, from the
        // integral of the density - and its limit along a level ray
        let e0 = exp(-b * h0);
        var density = e0 * (1.0 - 0.5 * x);
        if (abs(x) >= 1e-3) {
            density = (e0 - exp(-b * h1)) / x;
        }

        return 1.0 - exp(-uniform.dynSkyHaze.x * density * distance(worldPos, cameraPos));
    }

    // a linear color seen through the haze
    fn dynamicSkyHaze(color: vec3f, cameraPos: vec3f, worldPos: vec3f) -> vec3f {
        let amount = dynamicSkyHazeAmount(cameraPos, worldPos);
        return mix(color, dynamicSkyHazeColor(worldPos - cameraPos), vec3f(amount));
    }
`
);

// src/extras/effects/dynamic-sky/wgsl/lighting-blend-ps.js
var lighting_blend_ps_default2 = (
  /* wgsl */
  `
    var dynSkyBlendPrevious: texture_2d<f32>;
    var dynSkyBlendLatest: texture_2d<f32>;
    uniform dynSkyBlendWeight: f32;

    #include "decodePS"
    #include "encodePS"

    @fragment
    fn fragmentMain(input: FragmentInput) -> FragmentOutput {
        var output: FragmentOutput;
        let texel = vec2i(pcPosition.xy);
        let previous = decodeRGBP(textureLoad(dynSkyBlendPrevious, texel, 0));
        let latest = decodeRGBP(textureLoad(dynSkyBlendLatest, texel, 0));
        output.color = encodeRGBP(mix(previous, latest, vec3f(uniform.dynSkyBlendWeight)));
        return output;
    }
`
);

// src/extras/effects/dynamic-sky/wgsl/sky-ps.js
var sky_ps_default2 = (
  /* wgsl */
  `
    #include "gammaPS"
    #include "tonemappingPS"

    #ifdef PREPASS_PASS
        varying vLinearDepth: f32;
        #include "floatAsUintPS"
    #endif

    varying vViewDir: vec3f;

    #include "dynamicSkyAtmospherePS"

    #if defined(DYNSKY_CLOUDS_FLAT) || defined(DYNSKY_CLOUDS_VOLUMETRIC)
        #include "dynamicSkyCloudsPS"
    #endif

    #ifdef DYNSKY_CLOUDS_BUFFER
        var dynSkyCloudBuffer: texture_2d<f32>;
        var dynSkyCloudBufferSampler: sampler;
        uniform dynSkyBufferMatrix: mat3x3f;
        uniform dynSkyBufferProj: vec2f;

        #ifdef DYNSKY_CLOUDS_ENCODED
            uniform dynSkyCloudScale: f32;
        #endif

        fn dynamicSkyCloudsTap(uv: vec2f) -> vec4f {
            var clouds = textureSample(dynSkyCloudBuffer, dynSkyCloudBufferSampler, uv);
            #ifdef DYNSKY_CLOUDS_ENCODED
                clouds = vec4f(clouds.rgb / max(vec3f(1.0) - clouds.rgb, vec3f(1e-4)) * uniform.dynSkyCloudScale, clouds.a);
            #endif
            return clouds;
        }

        // the clouds, blurred over 3x3 texels of their texture - see the GLSL version
        fn dynamicSkyCloudsBuffer(viewDir: vec3f) -> vec4f {
            let v = uniform.dynSkyBufferMatrix * viewDir;
            let ndc = (v.xy / max(-v.z, 1e-6)) * uniform.dynSkyBufferProj;
            let uv = vec2f(ndc.x * 0.5 + 0.5, 0.5 - ndc.y * 0.5);
            let offset = (2.0 / 3.0) / vec2f(textureDimensions(dynSkyCloudBuffer, 0));
            return 0.25 * (
                dynamicSkyCloudsTap(uv + vec2f(-offset.x, -offset.y)) +
                dynamicSkyCloudsTap(uv + vec2f(offset.x, -offset.y)) +
                dynamicSkyCloudsTap(uv + vec2f(-offset.x, offset.y)) +
                dynamicSkyCloudsTap(uv + vec2f(offset.x, offset.y))
            );
        }
    #endif

    @fragment
    fn fragmentMain(input: FragmentInput) -> FragmentOutput {
        var output: FragmentOutput;
        #ifdef PREPASS_PASS
            output.color = float2vec4(input.vLinearDepth);
        #else
            var dir = normalize(input.vViewDir);
            dir.x = dir.x * -1.0;

            var ambient: vec3f;
            var linear = dynamicSkyBase(dir, &ambient);

            // the lights of the sky - the sun disc, and at night the stars and the moon
            var lights = dynSkySunDisc * (1.0 - uniform.dynSkyNightBlend);
            if (uniform.dynSkyNightBlend > 0.0) {
                lights = lights + dynamicSkyNightLights(dir) * uniform.dynSkyNightBlend;
            }

            // the clouds over the sky and its lights
            #if defined(DYNSKY_CLOUDS_BUFFER)
                linear = dynamicSkyCompositeClouds(linear, lights, dynamicSkyCloudsBuffer(input.vViewDir), dir);
            #elif defined(DYNSKY_CLOUDS_FLAT)
                linear = dynamicSkyCompositeClouds(linear, lights, dynamicSkyCloudsFlat(dir, ambient), dir);
            #elif defined(DYNSKY_CLOUDS_VOLUMETRIC)
                linear = dynamicSkyCompositeClouds(linear, lights, dynamicSkyCloudsVolumetric(dir, ambient), dir);
            #else
                linear = linear + lights;
            #endif

            // clamped to a value the bloom can handle, see the GLSL version
            linear = min(linear, vec3f(6000.0));

            output.color = vec4f(gammaCorrectOutput(toneMap(linear)), 1.0);
        #endif
        return output;
    }
`
);

